import json
n=30
g=[[0]*n for _ in range(n)]
starts=[1,8,15,22,29]
colors=[[3,2,2,3, None],[2,8,8,2,None],[3,2,2,3,None],[2,8,8,2,None],[None]*5]
# render tile shapes: full 5x5 border 4 / 3x3 inner colors; partial edge tiles
for i,r in enumerate(starts):
 for j,c in enumerate(starts):
  col=colors[i][j]
  for y in range(r,min(r+5,n)):
   for x in range(c,min(c+5,n)):
    if y==r or y==r+4 or x==c or x==c+4: g[y][x]=4
    elif col is not None: g[y][x]=col
# add rays from non-baseline 2 interiors
for i,r in enumerate(starts):
 for j,c in enumerate(starts):
  col=colors[i][j]
  if col not in (3,8): continue
  rs=range(r+1,min(r+4,n)); cs=range(c+1,min(c+4,n))
  for y in rs:
   for x in [c-2,c-1,c+5,c+6]:
    if 0<=x<n and g[y][x]==0: g[y][x]=col
  for x in cs:
   for y in [r-2,r-1,r+5,r+6]:
    if 0<=y<n and g[y][x]==0: g[y][x]=col
print(json.dumps(g,separators=(',',':')))

